import{_ as a,o as t,c as o,a6 as n}from"./chunks/framework.CKIbuWFA.js";const p=JSON.parse('{"title":"管理直播连接","description":"","frontmatter":{"title":"管理直播连接","docId":"user.live.connections","translationKey":"user.live.connections","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"37f7274550d3010051ab456da2a2091b650e5e7aaaf30756b6695435bcfc08c7","translationRevision":"a4d215f043de405759f16050ee99abdb357e8f61d6f31b6b243f81e64569b9ca","order":10},"headers":[],"relativePath":"zh/user/live/connections.md","filePath":"zh/user/live/connections.md","lastUpdated":1794611623000}'),r={name:"zh/user/live/connections.md"};function i(s,e,l,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="manage-live-connections" tabindex="-1">管理直播连接 <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to &quot;管理直播连接 {#manage-live-connections}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>连接指定主播，了解重新连接的行为，并单独配置插件服务器。你需要正常的<a href="./../installation.html">桌面安装</a>、网络访问和主播账号名。诊断操作系统问题前，请先查看<a href="./../requirements.html">系统要求</a>。</p><h2 id="connect-deliberately" tabindex="-1">按步骤建立连接 <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to &quot;按步骤建立连接 {#connect-deliberately}&quot;">​</a></h2><ol><li>打开 <strong>连接</strong>。输入账号名，可带或不带 <code>@</code>；显示名称并不是同一个标识符。</li><li>先关闭 <strong>使用会话 Cookie</strong>。如果 TikTok 需要授权会话，再启用并仅在遮蔽内容的字段中输入 Cookie。Cookie 只保存在内存中，不要粘贴到诊断信息或 Cloud 设置中。</li><li>直接尝试连接时，保持 <strong>监控并自动连接</strong> 关闭，再选择 <strong>连接</strong>。重试前，阅读状态和错误信息。</li><li>在<a href="./feed.html">直播事件流</a>中检查主播是否正确，以及是否收到新事件。已连接但没有互动的直播间可能不显示活动。</li><li>对同一主播使用 <strong>重新连接</strong>；切换主播前使用 <strong>断开连接</strong>。连接尝试忙碌时，<strong>取消</strong> 可停止该次尝试。</li></ol><p>直接连接成功后，可启用监控以等待主播开播。等待与检查不同于已连接。编辑锁定的账号名前，请先停止监控。选择最近的主播会立即开始连接，并非仅填入输入框。</p><p>探索器会提供发现的直播间，但结果可能过时。请先刷新，再判断直播间是否仍可用。下方面板中的插件服务器连接用于配置各自的服务；插件已连接并不代表 TikTok 或 Cloud 已通过身份验证。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>直接连接、监控及插件连接控件均可使用。重新连接同一主播会保留当前事件流上下文；切换主播会开始另一个上下文。实际能否访问 TikTok 取决于上游直播间和会话，本地测试成功并不构成保证。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>直播间离线时，请确认主播已经开播。会话或限流错误请遵循显示的重试条件。反复点击重新连接不会刷新身份验证。通过<a href="./../preferences/troubleshooting.html">故障排查</a>收集故障组件及发生时间，不要泄露凭据。</p>',11)])])}const f=a(r,[["render",i]]);export{p as __pageData,f as default};
